import * as Blockly from 'blockly/core';
import {extensionBlocks} from '../blocks/block-catalog.js';

export const cGenerator = new Blockly.CodeGenerator('BlockOS C');

cGenerator.INDENT = '    ';
cGenerator.ORDER_ATOMIC = 0;
cGenerator.ORDER_UNARY = 2;
cGenerator.ORDER_MULTIPLICATIVE = 3;
cGenerator.ORDER_ADDITIVE = 4;
cGenerator.ORDER_RELATIONAL = 6;
cGenerator.ORDER_EQUALITY = 7;
cGenerator.ORDER_LOGICAL_AND = 11;
cGenerator.ORDER_LOGICAL_OR = 12;
cGenerator.ORDER_NONE = 99;

const RUNTIME_HEADER = `// Generated by BlockOS Studio.
// This is freestanding x86_64 kernel C generated by BlockOS Studio v0.4.
// It can be compiled into a bootable GRUB ISO and run in QEMU.

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

void screen_clear(uint32_t colour);
void screen_print(const char *text);
void screen_print_line(const char *text);
void screen_print_i64(int64_t value);
void screen_set_pixel(int32_t x, int32_t y, uint32_t colour);
void cpu_halt(void);
void cpu_wait_for_interrupt(void);
uint8_t port_read8(uint16_t port);
void port_write8(uint16_t port, uint8_t value);
const char *blockos_string_join(const char *left, const char *right);
bool blockos_console_line_available(void);
const char *blockos_console_read_line(void);
bool blockos_string_equal_ignore_case(const char *left, const char *right);
uint32_t blockos_asset_count(void);
const char *blockos_asset_name(uint32_t index);
uint64_t blockos_asset_size(uint32_t index);
void blockos_print_asset_text(uint32_t index);
`;

function sanitizeIdentifier(value, fallback = 'unnamed') {
  const cleaned = String(value ?? '')
    .trim()
    .replace(/[^A-Za-z0-9_]/g, '_')
    .replace(/_+/g, '_');
  const withPrefix = /^[A-Za-z_]/.test(cleaned) ? cleaned : `_${cleaned}`;
  return withPrefix && withPrefix !== '_' ? withPrefix : fallback;
}

function cString(value) {
  return JSON.stringify(String(value ?? ''))
    .replace(/\\u2028/g, '\\u2028')
    .replace(/\\u2029/g, '\\u2029');
}

function valueOr(generator, block, inputName, order, fallback) {
  return generator.valueToCode(block, inputName, order) || fallback;
}

cGenerator.init = function init() {
  this.definitions_ = Object.create(null);
  this.functionPrototypes_ = new Set();
  this.extensionPrototypes_ = new Set();
  this.customTypeDefinitions_ = new Set();
};

cGenerator.finish = function finish(code) {
  const customTypes = [...this.customTypeDefinitions_].sort().join('\n');
  const prototypes = [...this.functionPrototypes_].sort().join('\n');
  const extensionPrototypes = [...this.extensionPrototypes_].sort().join('\n');
  const definitions = Object.values(this.definitions_).join('\n\n');
  const sections = [RUNTIME_HEADER.trimEnd()];

  if (customTypes) {
    sections.push(`// User-defined custom value types\n${customTypes}`);
  }

  if (extensionPrototypes) {
    sections.push(`// Runtime capability declarations\n${extensionPrototypes}`);
  }

  if (prototypes) {
    sections.push(`// Custom block declarations\n${prototypes}`);
  }

  if (definitions) {
    sections.push(`// Custom block implementations\n${definitions}`);
  }

  if (code.trim()) {
    sections.push(code.trim());
  } else {
    sections.push(`void kernel_main(void) {\n${this.INDENT}// Add a “when kernel starts” block.\n}`);
  }

  return `${sections.join('\n\n')}\n`;
};

cGenerator.scrub_ = function scrub(block, code, thisOnly) {
  const nextBlock = block.nextConnection?.targetBlock();
  const nextCode = thisOnly || !nextBlock ? '' : this.blockToCode(nextBlock);
  return code + nextCode;
};

cGenerator.forBlock.os_start = function osStart(block, generator) {
  const body = generator.statementToCode(block, 'BODY') || `${generator.INDENT}// Kernel is empty.\n`;
  return `void kernel_main(void) {\n${body}}\n`;
};

cGenerator.forBlock.os_print_text = function osPrintText(block, generator) {
  const text = valueOr(generator, block, 'TEXT', generator.ORDER_NONE, '\"\"');
  return `screen_print_line(${text});\n`;
};

cGenerator.forBlock.os_print_number = function osPrintNumber(block, generator) {
  const value = valueOr(generator, block, 'VALUE', generator.ORDER_NONE, '0');
  return `screen_print_i64((int64_t)(${value}));\n`;
};

cGenerator.forBlock.os_clear_screen = function osClearScreen(block, generator) {
  const colour = valueOr(generator, block, 'COLOUR', generator.ORDER_NONE, '0x000000u');
  return `screen_clear((uint32_t)(${colour}));\n`;
};

cGenerator.forBlock.os_set_pixel = function osSetPixel(block, generator) {
  const x = valueOr(generator, block, 'X', generator.ORDER_NONE, '0');
  const y = valueOr(generator, block, 'Y', generator.ORDER_NONE, '0');
  const colour = valueOr(generator, block, 'COLOUR', generator.ORDER_NONE, '0xFFFFFFu');
  return `screen_set_pixel((int32_t)(${x}), (int32_t)(${y}), (uint32_t)(${colour}));\n`;
};

cGenerator.forBlock.os_colour = function osColour(block, generator) {
  const raw = String(block.getFieldValue('COLOUR') || '#000000').trim();
  const hex = /^#[0-9A-Fa-f]{6}$/.test(raw) ? raw.slice(1) : '000000';
  return [`0x${hex.toUpperCase()}u`, generator.ORDER_ATOMIC];
};

cGenerator.forBlock.os_forever = function osForever(block, generator) {
  const body = generator.statementToCode(block, 'BODY') || `${generator.INDENT}// Empty loop.\n`;
  return `for (;;) {\n${body}}\n`;
};

cGenerator.forBlock.os_while = function osWhile(block, generator) {
  const condition = valueOr(generator, block, 'CONDITION', generator.ORDER_NONE, 'false');
  const body = generator.statementToCode(block, 'BODY') || `${generator.INDENT}// Nothing to repeat.\n`;
  return `while (${condition}) {\n${body}}\n`;
};

cGenerator.forBlock.os_if = function osIf(block, generator) {
  const condition = valueOr(generator, block, 'CONDITION', generator.ORDER_NONE, 'false');
  const body = generator.statementToCode(block, 'BODY') || `${generator.INDENT}// Condition body is empty.\n`;
  return `if (${condition}) {\n${body}}\n`;
};

cGenerator.forBlock.os_repeat = function osRepeat(block, generator) {
  const count = valueOr(generator, block, 'COUNT', generator.ORDER_NONE, '0');
  const body = generator.statementToCode(block, 'BODY') || `${generator.INDENT}// Nothing to repeat.\n`;
  const index = sanitizeIdentifier(`blockos_index_${block.id.slice(0, 6)}`);
  return `for (uint64_t ${index} = 0; ${index} < (uint64_t)(${count}); ++${index}) {\n${body}}\n`;
};

cGenerator.forBlock.os_text = function osText(block, generator) {
  return [cString(block.getFieldValue('TEXT')), generator.ORDER_ATOMIC];
};

cGenerator.forBlock.os_join_text = function osJoinText(block, generator) {
  const left = valueOr(generator, block, 'LEFT', generator.ORDER_NONE, '""');
  const right = valueOr(generator, block, 'RIGHT', generator.ORDER_NONE, '""');
  return [`blockos_string_join((const char *)(${left}), (const char *)(${right}))`, generator.ORDER_ATOMIC];
};

cGenerator.forBlock.os_input_line_available = function osInputLineAvailable(_block, generator) {
  return ['blockos_console_line_available()', generator.ORDER_ATOMIC];
};

cGenerator.forBlock.os_read_input_line = function osReadInputLine(_block, generator) {
  return ['blockos_console_read_line()', generator.ORDER_ATOMIC];
};

cGenerator.forBlock.os_text_equals_ignore_case = function osTextEqualsIgnoreCase(block, generator) {
  const left = valueOr(generator, block, 'LEFT', generator.ORDER_NONE, '""');
  const right = valueOr(generator, block, 'RIGHT', generator.ORDER_NONE, '""');
  return [`blockos_string_equal_ignore_case((const char *)(${left}), (const char *)(${right}))`, generator.ORDER_ATOMIC];
};

cGenerator.forBlock.os_number = function osNumber(block, generator) {
  const value = Number(block.getFieldValue('VALUE'));
  return [Number.isFinite(value) ? String(value) : '0', generator.ORDER_ATOMIC];
};

cGenerator.forBlock.os_boolean = function osBoolean(block, generator) {
  return [block.getFieldValue('VALUE') === 'TRUE' ? 'true' : 'false', generator.ORDER_ATOMIC];
};

cGenerator.forBlock.os_math = function osMath(block, generator) {
  const operators = {
    ADD: [' + ', generator.ORDER_ADDITIVE],
    SUBTRACT: [' - ', generator.ORDER_ADDITIVE],
    MULTIPLY: [' * ', generator.ORDER_MULTIPLICATIVE],
    DIVIDE: [' / ', generator.ORDER_MULTIPLICATIVE],
    MODULO: [' % ', generator.ORDER_MULTIPLICATIVE],
  };
  const [operator, order] = operators[block.getFieldValue('OP')] ?? operators.ADD;
  const left = valueOr(generator, block, 'A', order, '0');
  const right = valueOr(generator, block, 'B', order, '0');
  return [`${left}${operator}${right}`, order];
};

cGenerator.forBlock.os_compare = function osCompare(block, generator) {
  const operators = {
    EQ: '==',
    NEQ: '!=',
    LT: '<',
    LTE: '<=',
    GT: '>',
    GTE: '>=',
  };
  const operator = operators[block.getFieldValue('OP')] ?? '==';
  const order = operator === '==' || operator === '!=' ? generator.ORDER_EQUALITY : generator.ORDER_RELATIONAL;
  const left = valueOr(generator, block, 'A', order, '0');
  const right = valueOr(generator, block, 'B', order, '0');
  return [`${left} ${operator} ${right}`, order];
};

cGenerator.forBlock.os_logic = function osLogic(block, generator) {
  const isAnd = block.getFieldValue('OP') === 'AND';
  const operator = isAnd ? '&&' : '||';
  const order = isAnd ? generator.ORDER_LOGICAL_AND : generator.ORDER_LOGICAL_OR;
  const left = valueOr(generator, block, 'A', order, 'false');
  const right = valueOr(generator, block, 'B', order, 'false');
  return [`${left} ${operator} ${right}`, order];
};

cGenerator.forBlock.os_not = function osNot(block, generator) {
  const value = valueOr(generator, block, 'VALUE', generator.ORDER_UNARY, 'false');
  return [`!(${value})`, generator.ORDER_UNARY];
};

cGenerator.forBlock.os_var_declare = function osVarDeclare(block, generator) {
  const type = block.getFieldValue('TYPE') || 'uint32_t';
  const name = sanitizeIdentifier(block.getFieldValue('NAME'), 'value');
  const fallback = type === 'bool' ? 'false' : type === 'const char *' ? '""' : '0';
  const value = valueOr(generator, block, 'VALUE', generator.ORDER_NONE, fallback);
  return `${type} ${name} = (${type})(${value});\n`;
};

cGenerator.forBlock.os_var_set = function osVarSet(block, generator) {
  const name = sanitizeIdentifier(block.getFieldValue('NAME'), 'value');
  const value = valueOr(generator, block, 'VALUE', generator.ORDER_NONE, '0');
  return `${name} = ${value};\n`;
};

cGenerator.forBlock.os_var_get = function osVarGet(block, generator) {
  return [sanitizeIdentifier(block.getFieldValue('NAME'), 'value'), generator.ORDER_ATOMIC];
};

cGenerator.forBlock.os_port_read8 = function osPortRead8(block, generator) {
  const port = valueOr(generator, block, 'PORT', generator.ORDER_NONE, '0');
  return [`port_read8((uint16_t)(${port}))`, generator.ORDER_ATOMIC];
};

cGenerator.forBlock.os_port_write8 = function osPortWrite8(block, generator) {
  const value = valueOr(generator, block, 'VALUE', generator.ORDER_NONE, '0');
  const port = valueOr(generator, block, 'PORT', generator.ORDER_NONE, '0');
  return `port_write8((uint16_t)(${port}), (uint8_t)(${value}));\n`;
};

cGenerator.forBlock.os_halt = function osHalt() {
  return 'cpu_halt();\n';
};

cGenerator.forBlock.os_wait_interrupt = function osWaitInterrupt() {
  return 'cpu_wait_for_interrupt();\n';
};

cGenerator.forBlock.os_asset_count = function osAssetCount(_block, generator) {
  return ['blockos_asset_count()', generator.ORDER_ATOMIC];
};

cGenerator.forBlock.os_asset_name = function osAssetName(block, generator) {
  const index = valueOr(generator, block, 'INDEX', generator.ORDER_NONE, '0');
  return [`blockos_asset_name((uint32_t)(${index}))`, generator.ORDER_ATOMIC];
};

cGenerator.forBlock.os_asset_size = function osAssetSize(block, generator) {
  const index = valueOr(generator, block, 'INDEX', generator.ORDER_NONE, '0');
  return [`blockos_asset_size((uint32_t)(${index}))`, generator.ORDER_ATOMIC];
};

cGenerator.forBlock.os_print_asset_text = function osPrintAssetText(block, generator) {
  const index = valueOr(generator, block, 'INDEX', generator.ORDER_NONE, '0');
  return `blockos_print_asset_text((uint32_t)(${index}));\n`;
};

cGenerator.forBlock.os_function_def = function osFunctionDef(block, generator) {
  const name = sanitizeIdentifier(block.getFieldValue('NAME'), 'custom_block');
  const body = generator.statementToCode(block, 'BODY') || `${generator.INDENT}// Custom block body is empty.\n`;
  generator.functionPrototypes_.add(`static void ${name}(void);`);
  generator.definitions_[`custom_${name}`] = `static void ${name}(void) {\n${body}}`;
  return '';
};

cGenerator.forBlock.os_function_call = function osFunctionCall(block) {
  const name = sanitizeIdentifier(block.getFieldValue('NAME'), 'custom_block');
  return `${name}();\n`;
};

cGenerator.forBlock.os_comment = function osComment(block) {
  const text = String(block.getFieldValue('TEXT') ?? '').replace(/\r?\n/g, ' ').replace(/\*\//g, '* /');
  return `// ${text}\n`;
};


const extensionKindToCType = {
  cmd: 'void',
  num: 'uint64_t',
  bool: 'bool',
  text: 'const char *',
};

function extensionArgumentCType(type) {
  if (type === 'String') return 'const char *';
  if (type === 'Boolean') return 'bool';
  return 'uint64_t';
}

function extensionArgumentCode(generator, block, argument, index) {
  const fallback = argument.type === 'String' ? '""' : argument.type === 'Boolean' ? 'false' : '0';
  const value = valueOr(generator, block, `ARG${index}`, generator.ORDER_NONE, fallback);
  if (argument.type === 'String') return `(const char *)(${value})`;
  if (argument.type === 'Boolean') return `(bool)(${value})`;
  return `(uint64_t)(${value})`;
}

for (const spec of extensionBlocks) {
  cGenerator.forBlock[spec.type] = function extensionBlock(block, generator) {
    const returnType = extensionKindToCType[spec.kind];
    const parameters = spec.args.map((argument, index) => `${extensionArgumentCType(argument.type)} arg${index}`);
    generator.extensionPrototypes_.add(`${returnType} ${spec.cName}(${parameters.length ? parameters.join(', ') : 'void'});`);
    const args = spec.args.map((argument, index) => extensionArgumentCode(generator, block, argument, index));
    const call = `${spec.cName}(${args.join(', ')})`;
    if (spec.kind === 'cmd') return `${call};\n`;
    return [call, generator.ORDER_ATOMIC];
  };
}
